<?php

declare(strict_types=1);

use EventMenu\Core\Auth;
use EventMenu\Core\Security;
use EventMenu\Services\ProductionService;

Auth::requirePermission('orders.kitchen');$tenantId=em_require_tenant();$service=new ProductionService();
if($_SERVER['REQUEST_METHOD']==='POST'){
    em_post_csrf();$action=(string)($_POST['action']??'');
    try{
        if($action==='job-status'){$service->changeJobStatus((int)($_POST['job_id']??0),(string)($_POST['target']??''),(string)($_POST['reason']??''));em_flash('ok','Item de produção atualizado.');}
        elseif($action==='expedite-order'){$service->markOrderExpedited((int)($_POST['order_id']??0));em_flash('ok','Pedido liberado pela expedição.');}
        elseif(in_array($action,['print','reprint','auto-print'],true)){$type=$action==='reprint'?'reprint':($action==='auto-print'?'auto':'manual');$service->logPrint((int)($_POST['station_id']??0),(int)($_POST['order_id']??0),$type,(string)($_POST['reason']??''));em_flash('ok',$type==='reprint'?'Reimpressão registrada.':'Impressão registrada.');}
        else throw new RuntimeException('Ação inválida.');
    }catch(Throwable $e){em_flash('error',$e->getMessage());}
    em_go('kitchen');
}
$board=$service->board();$stations=$board['stations'];$jobs=$board['jobs'];$queue=$board['print_queue'];$expedition=$service->expedition();$byStation=[];foreach($jobs as$j)$byStation[(int)$j['station_id']][]=$j;$delayed=count(array_filter($jobs,fn($j)=>!empty($j['delayed'])));$preparing=count(array_filter($jobs,fn($j)=>$j['status']==='preparing'));$ready=count(array_filter($jobs,fn($j)=>$j['status']==='ready'));
em_header('Cozinha / KDS','kitchen');
?>
<section class="page-hero"><div><span class="eyebrow">KDS EM TEMPO REAL</span><h2>Produção por estação</h2><p>Cada setor recebe somente os itens roteados para ele. O pedido vai para expedição quando todos os setores envolvidos estiverem prontos.</p></div><div class="actions"><?php if(Auth::can('production.manage')):?><a class="button secondary" href="<?= Security::e(app_url('?route=production')) ?>">Configurar estações</a><?php endif;?></div></section>
<section class="grid" style="grid-template-columns:repeat(auto-fit,minmax(190px,1fr));margin-bottom:18px"><div class="card metric"><span class="muted">Itens ativos</span><strong><?= count($jobs) ?></strong></div><div class="card metric"><span class="muted">Em preparo</span><strong><?= $preparing ?></strong></div><div class="card metric"><span class="muted">Prontos</span><strong><?= $ready ?></strong></div><div class="card metric"><span class="muted">Atrasados</span><strong><?= $delayed ?></strong></div></section>
<?php if(!$stations):?><section class="card"><h2>Nenhuma estação configurada</h2><p class="muted">Cadastre cozinha, bar, chapa, fritadeira ou outro setor em Produção / Estações e depois roteie os produtos.</p></section><?php endif;?>
<?php foreach($stations as$station):$rows=$byStation[(int)$station['id']]??[];?><section class="card" style="margin-bottom:18px"><div class="section-head"><div><span class="eyebrow"><?= Security::e(mb_strtoupper((string)$station['station_type'])) ?></span><h2><?= Security::e($station['name']) ?></h2><span class="muted">SLA padrão <?= (int)$station['sla_minutes'] ?> min · impressão <?= Security::e($station['printer_mode']) ?></span></div><span class="badge"><?= count($rows) ?> itens</span></div><?php if(!$rows):?><p class="muted">Sem itens aguardando nesta estação.</p><?php else:?><div class="grid" style="grid-template-columns:repeat(auto-fit,minmax(270px,1fr))"><?php foreach($rows as$j):?><article class="card" style="border-color:<?= $j['delayed']?'#7f3541':'var(--line)' ?>"><div class="section-head"><div><strong>Pedido #<?= (int)$j['order_id'] ?></strong><br><span class="muted"><?= Security::e($j['table_name']??$j['customer_name']??$j['channel']) ?></span></div><span class="status-pill <?= $j['delayed']?'cancelled':($j['status']==='ready'?'active':'') ?>"><?= $j['delayed']?'ATRASADO · ':'' ?><?= Security::e($j['status']) ?></span></div><h3><?= Security::e((string)$j['quantity']) ?>× <?= Security::e($j['description']) ?></h3><div class="muted">Aguardando <?= (int)$j['elapsed_minutes'] ?> min · meta <?= (int)$j['prep_minutes'] ?> min<?php if((int)$j['change_version']>1):?><br><strong>⚠ ALTERADO APÓS ENVIO · versão <?= (int)$j['change_version'] ?></strong><?php endif;?></div><?php if($j['order_notes']):?><div class="alert">Obs. do pedido: <?= Security::e($j['order_notes']) ?></div><?php endif;?><form method="post" style="margin-top:12px"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="job-status"><input type="hidden" name="job_id" value="<?= (int)$j['id'] ?>"><?php if($j['status']==='received'):?><input type="hidden" name="target" value="preparing"><button class="primary" style="width:100%">Iniciar preparo</button><?php elseif($j['status']==='preparing'):?><input type="hidden" name="target" value="ready"><button class="primary" style="width:100%">Marcar pronto</button><?php else:?><button class="secondary" disabled style="width:100%">Aguardando expedição</button><?php endif;?></form><div class="actions" style="margin-top:9px"><?php if(Auth::can('production.print')):?><form method="post"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="print"><input type="hidden" name="station_id" value="<?= (int)$station['id'] ?>"><input type="hidden" name="order_id" value="<?= (int)$j['order_id'] ?>"><button class="secondary compact" onclick="setTimeout(()=>window.print(),50)">Imprimir setor</button></form><details><summary class="button secondary compact">Reimprimir</summary><form method="post" class="actions" style="margin-top:8px"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="reprint"><input type="hidden" name="station_id" value="<?= (int)$station['id'] ?>"><input type="hidden" name="order_id" value="<?= (int)$j['order_id'] ?>"><input name="reason" required maxlength="500" placeholder="Motivo obrigatório"><button class="secondary compact">Registrar</button></form></details><?php endif;?></div></article><?php endforeach;?></div><?php endif;?></section><?php endforeach;?>
<section class="card" style="margin-bottom:18px"><div class="section-head"><div><span class="eyebrow">EXPEDIÇÃO</span><h2>Juntar setores</h2><p class="muted">Só libere quando chapa, fritadeira, bar e demais estações do pedido estiverem prontos.</p></div><span class="badge"><?= count($expedition) ?> pedidos</span></div><?php if(!$expedition):?><p class="muted">Nenhum pedido em produção.</p><?php else:?><div class="table-wrap"><table class="table"><thead><tr><th>Pedido</th><th>Destino</th><th>Produção</th><th>Status</th><th>Ação</th></tr></thead><tbody><?php foreach($expedition as$o):?><tr><td><strong>#<?= (int)$o['id'] ?></strong><br><span class="muted"><?= Security::e($o['channel']) ?></span></td><td><?= Security::e($o['table_name']??$o['customer_name']??'Balcão') ?></td><td><?= (int)$o['jobs_ready'] ?>/<?= max(0,(int)$o['jobs_total']-(int)$o['jobs_cancelled']) ?> prontos</td><td><span class="status-pill <?= $o['all_ready']?'active':'' ?>"><?= $o['all_ready']?'PRONTO PARA EXPEDIR':'AGUARDANDO SETORES' ?></span></td><td><?php if($o['all_ready']&&Auth::can('orders.dispatch')):?><form method="post"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="expedite-order"><input type="hidden" name="order_id" value="<?= (int)$o['id'] ?>"><button class="primary">Expedir</button></form><?php else:?>—<?php endif;?></td></tr><?php endforeach;?></tbody></table></div><?php endif;?></section>
<?php if($queue):?><section class="card"><div class="section-head"><div><span class="eyebrow">IMPRESSÃO AUTOMÁTICA</span><h2>Fila pendente</h2></div><span class="badge"><?= count($queue) ?></span></div><div class="table-wrap"><table class="table"><thead><tr><th>Pedido</th><th>Estação</th><th>Solicitado</th><th></th></tr></thead><tbody><?php foreach($queue as$q):?><tr><td>#<?= (int)$q['order_id'] ?></td><td><?= Security::e($q['station_name']) ?></td><td><?= Security::e($q['created_at']) ?></td><td><form method="post"><input type="hidden" name="_csrf" value="<?= em_csrf() ?>"><input type="hidden" name="action" value="auto-print"><input type="hidden" name="station_id" value="<?= (int)$q['station_id'] ?>"><input type="hidden" name="order_id" value="<?= (int)$q['order_id'] ?>"><button class="secondary" onclick="setTimeout(()=>window.print(),50)">Imprimir e confirmar</button></form></td></tr><?php endforeach;?></tbody></table></div></section><?php endif;?>
<script>setTimeout(()=>{if(!document.querySelector('input:focus,textarea:focus,select:focus,details[open]'))location.reload()},5000);</script>
<?php em_footer();
